import{_ as o,C as t,o as r,c as i,a5 as d,E as n,j as a,a as l}from"./chunks/framework.BwlBv862.js";const y=JSON.parse('{"title":"Consultar estadísticas por fechas","description":"","frontmatter":{"title":"Consultar estadísticas por fechas","docId":"user.points.statistics","translationKey":"user.points.statistics","locale":"es","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"a7333d75baa9aec6e0c4afb69d1c773575a56ee8da982f0fa5a11a73b903ec2d","translationRevision":"ca77e6883eafb2541f8405005c4ccad0d8277176b2782c661b5302879cb625d0","order":20},"headers":[],"relativePath":"es/user/points/statistics.md","filePath":"es/user/points/statistics.md","lastUpdated":1794611623000}'),c={name:"es/user/points/statistics.md"};function u(p,e,m,h,f,b){const s=t("DemoFrame");return r(),i("div",null,[e[0]||(e[0]=d('<h1 id="review-statistics-across-dates" tabindex="-1">Consultar estadísticas por fechas <a class="header-anchor" href="#review-statistics-across-dates" aria-label="Permalink to &quot;Consultar estadísticas por fechas {#review-statistics-across-dates}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Compara la actividad de un creador durante un período útil y comprende por qué sus totales difieren del feed visible o del saldo de puntos. Necesitas actividad registrada en la instalación local y el creador correcto seleccionado desde <a href="./../live/connections.html">Connections</a>. El inicio de sesión en Cloud no proporciona estas estadísticas locales.</p><h2 id="query-the-recorded-period" tabindex="-1">Consultar el período registrado <a class="header-anchor" href="#query-the-recorded-period" aria-label="Permalink to &quot;Consultar el período registrado {#query-the-recorded-period}&quot;">​</a></h2><ol><li>Abre <strong>Analytics</strong> y confirma el creador junto a los controles de fecha. El creador seleccionado determina qué agregados guardados se consultan.</li><li>Elige <strong>Today</strong>, <code>7d</code>, <code>30d</code>, <code>90d</code> o un rango personalizado. Para fechas personalizadas, establece inicio y fin explícitamente y comprueba su orden.</li><li>Lee el intervalo mostrado y el número de sesiones antes de comparar resultados. Los límites diarios utilizan un desplazamiento horario; cambiar la zona del equipo puede modificar la interpretación del período.</li><li>Selecciona la métrica: chats, regalos, likes, diamantes o pico de espectadores. Usa los gráficos de actividad para comparar períodos y la tabla de contribuyentes para revisar los espectadores destacados devueltos.</li><li>Busca en la tabla un espectador incluido entre los datos recibidos. Esta búsqueda no recorre sin límites todos los espectadores observados alguna vez.</li><li>Pulsa <strong>Refresh</strong> después de nueva actividad o al volver a la página. Anota creador, fechas y métrica junto con cualquier cifra que compartas.</li></ol><p>La página actual llama a la operación nativa <code>analytics.summary</code> con un creador y un intervalo. Lee agregados persistentes, incluidas sesiones registradas previamente; no se limita a los eventos que permanecen en el feed actual. La base de estadísticas guarda agregados y no una transcripción del chat.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado y estado {#expected-result-and-status}&quot;">​</a></h2><p>Están disponibles las estadísticas locales persistentes y las consultas por fechas. Es normal que períodos sin actividad devuelvan resultados vacíos. Los saldos pueden diferir porque las <a href="./rules.html">tasas</a>, los ajustes manuales y las automatizaciones miden otra cosa. Diamantes, número de regalos y puntos no son unidades intercambiables.</p><h2 id="recovery" tabindex="-1">Recuperación <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperación {#recovery}&quot;">​</a></h2><p>Si faltan datos, borra la búsqueda, amplía las fechas, confirma el creador y actualiza. Ante un error del host, conserva su código de diagnóstico y repite cuando se recupere la conexión. Vaciar el feed no borra estadísticas. Un directorio de datos nuevo no contiene historial anterior; consulta <a href="./../preferences/backups.html">copias de seguridad</a> para trasladar una instalación.</p>',10)),n(s,{scenario:"analytics",locale:"es",title:"Demo de analytics"}),e[1]||(e[1]=a("h2",{id:"operational-details",tabindex:"-1"},[l("Detalles de operación "),a("a",{class:"header-anchor",href:"#operational-details","aria-label":'Permalink to "Detalles de operación {#operational-details}"'},"​")],-1)),e[2]||(e[2]=a("p",null,"Analytics solicita actualmente 10 contribuyentes principales para el creador y fechas elegidos. La búsqueda filtra ese subconjunto, no consulta todos los espectadores. Estos agregados persistentes tienen períodos y unidades distintos de los rankings de diamantes/likes de la sesión y del saldo de puntos. Conserva creador, fechas y métrica al exportar o comparar.",-1))])}const g=o(c,[["render",u]]);export{y as __pageData,g as default};
